export interface Monster {
  id: string;
  name: string;
  race: string;
  archetype: string;
  imageUrl: string;
  attributes: {
    agility: string;
    cunning: string;
    spirit: string;
    strength: string;
    vigor: string;
  };
  skills: string[];
  movement: string;
  parry: number;
  toughness: string;
  size?: number;
  abilities: { name: string; description: string }[];
  advantages?: string[];
  complications?: string[];
  powers?: string;
  weapons?: string;
  equipment?: string;
  history: string;
  sourcebook: string;
}

export type MonsterArchetype = 'Soldier' | 'Brute' | 'Sharpshooter' | 'Shadow Mage' | 'Beast' | 'Elemental' | 'Undead';

export interface MonsterTemplate {
  id?: string;
  name: string;
  race: string;
  archetype: string;
  attributes: {
    agility: string;
    cunning: string;
    spirit: string;
    strength: string;
    vigor: string;
  };
  skills: string; 
  movement: string;
  parry: number;
  toughness: string;
  abilities: { name: string; description: string }[];
  advantages: string;
  complications: string;
  weapons: string;
  history: string;
  size: number;
  imageUrl?: string;
}

import React, { useState, useRef, ChangeEvent, useEffect } from 'react';
import { MonsterArchetype, MonsterTemplate, Monster } from '../types';
import { generateMonsterStory } from '../services/geminiService';
import { addCustomMonster } from '../services/customMonsterService';
import { SparklesIcon, ImageIcon } from './icons';

const DICE_TYPES = ['d4', 'd6', 'd8', 'd10', 'd12', 'd12+1', 'd12+2', 'd12+3', 'd12+4', 'd12+5', 'd12+6'];

const MONSTER_TEMPLATES: Record<MonsterArchetype, Omit<MonsterTemplate, 'name' | 'history'>> = {
  Soldier: {
    race: 'Humano', archetype: 'Soldado Assombrado', size: 0,
    attributes: { agility: 'd8', cunning: 'd6', spirit: 'd6', strength: 'd8', vigor: 'd8' },
    skills: 'Lutar d8, Intimidar d6, Atirar d8, Perceber d6',
    movement: '6', parry: 6, toughness: '8 (2)',
    abilities: [
      { name: 'Destemido', description: 'Imune a Medo e Intimidação.' },
      { name: 'Formação de Batalha', description: 'Recebe +1 de Aparar quando adjacente a um aliado.' }
    ],
    weapons: 'Espada Longa (For+d8), Armadura de Couro (+2)',
    advantages: 'Reflexos em Combate', complications: 'Leal (maior)',
  },
  Brute: {
    race: 'Criatura', archetype: 'Besta Feroz', size: 2,
    attributes: { agility: 'd6', cunning: 'd4', spirit: 'd6', strength: 'd12', vigor: 'd10' },
    skills: 'Lutar d10, Intimidar d10, Perceber d6',
    movement: '8', parry: 7, toughness: '9 (2)',
    abilities: [
      { name: 'Pele Grossa', description: 'Armadura natural +2.' },
      { name: 'Frenesi', description: 'Pode fazer um ataque de Lutar extra por turno com -2 de penalidade.' },
      { name: 'Tamanho +2', description: 'A criatura é maior que um humano normal.'}
    ],
    weapons: 'Garras e Presas (For+d8)',
    advantages: 'Brutamontes, Frenesi', complications: 'Sanguinário (maior)',
  },
  Sharpshooter: {
    race: 'Elfo', archetype: 'Atirador Espectral', size: 0,
    attributes: { agility: 'd10', cunning: 'd8', spirit: 'd6', strength: 'd6', vigor: 'd6' },
    skills: 'Atirar d10, Furtividade d8, Perceber d8',
    movement: '6', parry: 5, toughness: '5',
    abilities: [
        { name: 'Visão no Escuro', description: 'Ignora penalidades por penumbra ou escuridão.' },
        { name: 'Tiro Certeiro', description: 'Pode mirar por um turno para adicionar +2 ao seu próximo tiro.'}
    ],
    weapons: 'Arco Longo (2d6, Alcance 15/30/60)',
    advantages: 'Atirador, Nervos de Aço', complications: 'Cauteloso (maior)',
  },
  'Shadow Mage': {
    race: 'Aparição', archetype: 'Mago das Sombras', size: 0,
    attributes: { agility: 'd6', cunning: 'd8', spirit: 'd10', strength: 'd4', vigor: 'd6' },
    skills: 'Conjurar d10, Ocultismo d8, Intimidar d8, Perceber d8',
    movement: '6', parry: 4, toughness: '5',
    abilities: [
      { name: 'Etéreo', description: 'Imaterial, só pode ser ferido por ataques mágicos.' },
      { name: 'Toque Sombrio', description: 'Ataque de toque drena 1 nível de Fadiga da vítima.'}
    ],
    weapons: 'Magias (Ex: Rajada Sombria 2d6, Medo)',
    advantages: 'AA Magia', complications: 'Vulnerabilidade: Luz (maior)',
  },
  Beast: {
    race: 'Besta', archetype: 'Predador Alfa', size: 0,
    attributes: { agility: 'd8', cunning: 'd6', spirit: 'd6', strength: 'd8', vigor: 'd8' },
    skills: 'Lutar d8, Perceber d8, Furtividade d8, Atletismo d8',
    movement: '8', parry: 6, toughness: '6',
    abilities: [
      { name: 'Sentidos Aguçados', description: '+2 em testes de Perceber e Rastrear.' },
      { name: 'Armas Naturais', description: 'Garras ou Mordida.' }
    ],
    weapons: 'Garras/Mordida (For+d4)',
    advantages: 'Prontidão', complications: 'Mudo (maior)',
  },
  Elemental: {
    race: 'Elemental', archetype: 'Espírito da Natureza', size: 0,
    attributes: { agility: 'd8', cunning: 'd6', spirit: 'd8', strength: 'd8', vigor: 'd8' },
    skills: 'Lutar d8, Atirar d8, Intimidar d8',
    movement: '6', parry: 6, toughness: '6',
    abilities: [
      { name: 'Elemental', description: 'Não respira, imune a veneno e doenças. Ignora penalidades de ferimento.' },
      { name: 'Invulnerabilidade', description: 'Imune ao seu elemento de origem.' }
    ],
    weapons: 'Pancada (For+d6), Rajada Elemental (2d6)',
    advantages: '', complications: 'Vulnerabilidade (Elemento Oposto)',
  },
  Undead: {
    race: 'Morto-Vivo', archetype: 'Guerreiro Esqueleto', size: 0,
    attributes: { agility: 'd6', cunning: 'd4', spirit: 'd4', strength: 'd6', vigor: 'd6' },
    skills: 'Lutar d6, Intimidar d6, Perceber d4',
    movement: '6', parry: 5, toughness: '7',
    abilities: [
      { name: 'Morto-Vivo', description: '+2 Resistência; +2 para recuperar de Abalado; ignora 1 ponto de penalidade de Ferimento; Imune a doenças/venenos.' },
      { name: 'Destemido', description: 'Imune a Medo e Intimidação.' }
    ],
    weapons: 'Espada Enferrujada (For+d4)',
    advantages: '', complications: '',
  }
};

const initialMonster: MonsterTemplate = { name: '', history: '', ...MONSTER_TEMPLATES.Soldier };

const monsterToTemplate = (monster: Monster): MonsterTemplate => ({
  id: monster.id,
  name: monster.name,
  race: monster.race,
  archetype: monster.archetype,
  attributes: monster.attributes,
  skills: monster.skills.join(', '),
  movement: monster.movement,
  parry: monster.parry,
  toughness: monster.toughness,
  size: monster.size ?? 0,
  abilities: monster.abilities,
  advantages: monster.advantages?.join(', ') || '',
  complications: monster.complications?.join(', ') || '',
  weapons: monster.weapons || '',
  history: monster.history,
  imageUrl: monster.imageUrl,
});

const MonsterCreator: React.FC<{ monsterToEdit: Monster | null, onSaveSuccess: () => void }> = ({ monsterToEdit, onSaveSuccess }) => {
  const [monster, setMonster] = useState<MonsterTemplate>(initialMonster);
  const [imageFile, setImageFile] = useState<File | null>(null);
  const [imagePreview, setImagePreview] = useState<string | null>(null);
  const [isGenerating, setIsGenerating] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (monsterToEdit) {
      setMonster(monsterToTemplate(monsterToEdit));
      setImagePreview(monsterToEdit.imageUrl);
      setImageFile(null);
    } else {
      setMonster(initialMonster);
      setImagePreview(null);
      setImageFile(null);
    }
  }, [monsterToEdit]);

  const handleArchetypeChange = (e: ChangeEvent<HTMLSelectElement>) => {
    const newArchetype = e.target.value as MonsterArchetype;
    setMonster({ ...monster, ...MONSTER_TEMPLATES[newArchetype] });
  };

  const handleValueChange = (e: ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setMonster(prev => ({...prev, [name]: name === 'parry' || name === 'size' ? parseInt(value, 10) : value }));
  };

  const handleAttributeChange = (e: ChangeEvent<HTMLSelectElement>) => {
    const { name, value } = e.target;
    setMonster(prev => ({ ...prev, attributes: { ...prev.attributes, [name]: value } }));
  }

  const handleImageUpload = (e: ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      setImageFile(file);
      setImagePreview(URL.createObjectURL(file));
    }
  };

  const handleGenerateStory = async () => {
    if (!monster.name) {
        alert("Please enter a name for your monster first.");
        return;
    }
    setIsGenerating(true);
    const abilitiesText = monster.abilities.map(a => a.name).join(', ');
    const generatedHistory = await generateMonsterStory({
      name: monster.name, archetype: monster.archetype, race: monster.race,
      abilities: abilitiesText, skills: monster.skills, weapons: monster.weapons,
      toughness: monster.toughness, attributes: monster.attributes,
    });
    setMonster(prev => ({...prev, history: generatedHistory}));
    setIsGenerating(false);
  };

  const handleSave = async () => {
    await addCustomMonster(monster, imageFile ?? undefined);
    alert(`Monster "${monster.name}" saved!`);
    onSaveSuccess();
  };

  const canSave = monster.name.trim() !== '';

  return (
    <div className="max-w-6xl mx-auto bg-slate-950 p-6 sm:p-8 rounded-lg shadow-2xl shadow-red-900/20 ring-1 ring-slate-800">
      <h2 className="font-creepster text-4xl text-red-600 mb-6 tracking-wider">{monsterToEdit ? 'Edit a Legend' : 'Create a New Legend'}</h2>

      <form onSubmit={e => { e.preventDefault(); handleSave(); }}>
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 mb-6">
          <div className="lg:col-span-1 space-y-4">
            <div 
                className="w-full h-64 bg-slate-900 rounded-md flex items-center justify-center border-2 border-dashed border-slate-700 cursor-pointer hover:border-red-600 transition-colors"
                onClick={() => fileInputRef.current?.click()}
            >
                <input type="file" accept="image/*" ref={fileInputRef} onChange={handleImageUpload} className="hidden" />
                {imagePreview ? (
                    <img src={imagePreview} alt="Monster Preview" className="w-full h-full object-cover rounded-md" />
                ) : (
                    <div className="text-center">
                        <ImageIcon />
                        <p className="mt-2 text-sm text-slate-400">Upload Image</p>
                    </div>
                )}
            </div>
             <div>
                <label htmlFor="name" className="block text-sm font-medium text-slate-400 mb-1">Monster Name</label>
                <input required type="text" name="name" id="name" value={monster.name} onChange={handleValueChange} className="w-full bg-slate-800 border-slate-700 rounded-md p-2 text-slate-200 focus:ring-red-500 focus:border-red-500"/>
            </div>
            <div>
                <label htmlFor="archetypeSelect" className="block text-sm font-medium text-slate-400 mb-1">Archetype Template</label>
                <select id="archetypeSelect" value={Object.keys(MONSTER_TEMPLATES).find(key => MONSTER_TEMPLATES[key as MonsterArchetype].archetype === monster.archetype) || 'Soldier'} onChange={handleArchetypeChange} className="w-full bg-slate-800 border-slate-700 rounded-md p-2 text-slate-200 focus:ring-red-500 focus:border-red-500">
                {Object.keys(MONSTER_TEMPLATES).map(key => (
                    <option key={key} value={key}>{key}</option>
                ))}
                </select>
            </div>
             <div>
                <label htmlFor="race" className="block text-sm font-medium text-slate-400 mb-1">Race</label>
                <input type="text" name="race" id="race" value={monster.race} onChange={handleValueChange} className="w-full bg-slate-800 border-slate-700 rounded-md p-2 text-slate-200 focus:ring-red-500 focus:border-red-500"/>
            </div>
          </div>
          <div className="lg:col-span-2 grid grid-cols-1 md:grid-cols-2 gap-x-8 gap-y-4">
              <div>
                <h3 className="font-creepster text-xl text-red-500 mb-2 tracking-wider">Attributes</h3>
                <div className="space-y-2">
                    {Object.entries(monster.attributes).map(([key, value]) => (
                        <div key={key} className="flex items-center gap-2">
                            <label htmlFor={key} className="w-20 capitalize text-sm text-slate-400">{key}</label>
                            <select name={key} id={key} value={value} onChange={handleAttributeChange} className="w-full bg-slate-800 border-slate-700 rounded-md p-1.5 text-sm text-slate-200 focus:ring-red-500 focus:border-red-500">
                                {DICE_TYPES.map(dice => <option key={dice} value={dice}>{dice}</option>)}
                            </select>
                        </div>
                    ))}
                </div>
              </div>
               <div>
                <h3 className="font-creepster text-xl text-red-500 mb-2 tracking-wider">Combat</h3>
                <div className="space-y-2">
                    <div className="flex items-center gap-2">
                        <label htmlFor="movement" className="w-24 text-sm text-slate-400">Movement</label>
                        <input type="text" name="movement" id="movement" value={monster.movement} onChange={handleValueChange} className="w-full bg-slate-800 border-slate-700 rounded-md p-1.5 text-sm text-slate-200"/>
                    </div>
                    <div className="flex items-center gap-2">
                        <label htmlFor="parry" className="w-24 text-sm text-slate-400">Parry</label>
                        <input type="number" name="parry" id="parry" value={monster.parry} onChange={handleValueChange} className="w-full bg-slate-800 border-slate-700 rounded-md p-1.5 text-sm text-slate-200"/>
                    </div>
                    <div className="flex items-center gap-2">
                        <label htmlFor="toughness" className="w-24 text-sm text-slate-400">Toughness</label>
                        <input type="text" name="toughness" id="toughness" value={monster.toughness} onChange={handleValueChange} className="w-full bg-slate-800 border-slate-700 rounded-md p-1.5 text-sm text-slate-200"/>
                    </div>
                     <div className="flex items-center gap-2">
                        <label htmlFor="size" className="w-24 text-sm text-slate-400">Size</label>
                        <input type="number" name="size" id="size" value={monster.size} onChange={handleValueChange} className="w-full bg-slate-800 border-slate-700 rounded-md p-1.5 text-sm text-slate-200"/>
                    </div>
                </div>
              </div>

              <div className="md:col-span-2">
                <label htmlFor="skills" className="block text-sm font-medium text-slate-400 mb-1">Skills <span className="text-xs text-slate-500">(comma-separated)</span></label>
                <textarea name="skills" id="skills" value={monster.skills} onChange={handleValueChange} rows={3} className="w-full bg-slate-800 border-slate-700 rounded-md p-2 text-sm text-slate-200 focus:ring-red-500 focus:border-red-500" placeholder="e.g., Lutar d8, Intimidar d6"></textarea>
              </div>

              <div className="md:col-span-2">
                <label htmlFor="weapons" className="block text-sm font-medium text-slate-400 mb-1">Weapons & Equipment</label>
                <textarea name="weapons" id="weapons" value={monster.weapons} onChange={handleValueChange} rows={3} className="w-full bg-slate-800 border-slate-700 rounded-md p-2 text-sm text-slate-200 focus:ring-red-500 focus:border-red-500"></textarea>
              </div>
          </div>
        </div>

        <div className="space-y-4">
            <div>
              <h3 className="font-creepster text-xl text-red-500 mb-2 tracking-wider">Abilities, Advantages & Complications</h3>
               <div className="grid md:grid-cols-2 gap-4">
                   <textarea name="abilities" value={monster.abilities.map(a => `${a.name}: ${a.description}`).join('\n')} disabled rows={4} className="w-full bg-slate-900 border-slate-700 rounded-md p-2 text-sm text-slate-400" placeholder="Abilities are set by the template for now. Full customization coming soon!"></textarea>
                   <div className="space-y-2">
                       <input name="advantages" value={monster.advantages} onChange={handleValueChange} className="w-full bg-slate-800 border-slate-700 rounded-md p-2 text-sm text-slate-200" placeholder="Advantages (comma-separated)"/>
                       <input name="complications" value={monster.complications} onChange={handleValueChange} className="w-full bg-slate-800 border-slate-700 rounded-md p-2 text-sm text-slate-200" placeholder="Complications (comma-separated)"/>
                   </div>
               </div>
            </div>

            <div>
                <div className="flex justify-between items-center mb-1">
                <label htmlFor="history" className="block text-sm font-medium text-slate-400">Backstory</label>
                <button
                    type="button" onClick={handleGenerateStory} disabled={isGenerating}
                    className="flex items-center gap-2 text-sm bg-red-600 text-white px-3 py-1 rounded-md hover:bg-red-700 transition-colors disabled:bg-slate-600 disabled:cursor-not-allowed"
                >
                    <SparklesIcon />
                    {isGenerating ? 'Generating...' : 'Generate with AI'}
                </button>
                </div>
                <textarea name="history" id="history" value={monster.history} onChange={handleValueChange} rows={6} className="w-full bg-slate-800 border-slate-700 rounded-md p-2 text-slate-200 focus:ring-red-500 focus:border-red-500" placeholder="Describe the monster's origins... or let AI do it for you!"></textarea>
            </div>

            <button 
              type="submit" 
              disabled={!canSave || isGenerating}
              className="w-full bg-red-600 text-white font-bold py-3 rounded-md hover:bg-red-700 transition-colors disabled:bg-slate-600 disabled:cursor-not-allowed"
            >
                {monsterToEdit ? 'Update Monster' : 'Save Monster'}
            </button>
        </div>

      </form>
    </div>
  );
};

export default MonsterCreator;

import React, { useState, useMemo, useEffect } from 'react';
import { monsters as predefinedMonsters } from '../services/monsterData';
import { getCustomMonsters, deleteCustomMonster } from '../services/customMonsterService';
import { Monster } from '../types';
import { ArrowLeftIcon, AddIcon, PrintIcon, CloseIcon, EditIcon, TrashIcon, BookIcon, SearchIcon } from './icons';
import { generatePdf } from '../services/pdfService';

type PdfTemplate = 'simple' | 'complete' | 'card';

const PrintModal: React.FC<{ 
    isOpen: boolean; 
    onClose: () => void; 
    onPrint: (template: PdfTemplate) => void;
    isPrinting: boolean;
}> = ({ isOpen, onClose, onPrint, isPrinting }) => {
    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-black/70 flex items-center justify-center z-50">
            <div className="bg-slate-800 p-8 rounded-lg shadow-xl max-w-sm w-full">
                <div className="flex justify-between items-center mb-6">
                    <h2 className="font-creepster text-2xl text-red-500">Print Collection</h2>
                    <button onClick={onClose}><CloseIcon /></button>
                </div>
                <p className="text-slate-400 mb-6">Select a format to print the current collection of monsters.</p>
                <div className="space-y-4">
                    <button onClick={() => onPrint('simple')} disabled={isPrinting} className="w-full text-left p-4 bg-slate-700 hover:bg-slate-600 rounded-md">
                        <h3 className="font-bold">Simple List</h3>
                        <p className="text-sm text-slate-400">A compact, multi-column list of names and stats.</p>
                    </button>
                    <button onClick={() => onPrint('complete')} disabled={isPrinting} className="w-full text-left p-4 bg-slate-700 hover:bg-slate-600 rounded-md">
                        <h3 className="font-bold">Complete Sheets</h3>
                        <p className="text-sm text-slate-400">Full-page bestiary entries for each monster.</p>
                    </button>
                    <button onClick={() => onPrint('card')} disabled={isPrinting} className="w-full text-left p-4 bg-slate-700 hover:bg-slate-600 rounded-md">
                        <h3 className="font-bold">Monster Cards</h3>
                        <p className="text-sm text-slate-400">Double-sided, tarot-sized cards for printing.</p>
                    </button>
                </div>
                {isPrinting && <p className="text-center text-red-500 mt-4">Generating PDF, please wait...</p>}
            </div>
        </div>
    );
};

const StatBlock: React.FC<{ title: string; children: React.ReactNode }> = ({ title, children }) => (
    <div className="mb-4">
        <h4 className="font-creepster text-xl text-red-500 mb-2 tracking-wider">{title}</h4>
        <div className="text-slate-300 text-sm leading-relaxed">{children}</div>
    </div>
);

const MonsterDetail: React.FC<{ monster: Monster; onBack: () => void; onEdit: (monster: Monster) => void; onDelete: (id: string) => void; }> = ({ monster, onBack, onEdit, onDelete }) => {
  const [isPrinting, setIsPrinting] = useState(false);

  const handlePrint = async () => {
      setIsPrinting(true);
      await generatePdf([monster], 'complete');
      setIsPrinting(false);
  }

  const isCustom = monster.sourcebook === 'Custom Creations';

  return (
    <div className="bg-slate-950 p-4 sm:p-8 rounded-lg shadow-2xl shadow-red-900/20 ring-1 ring-slate-800">
        <div className="flex justify-between items-start mb-6">
            <button onClick={onBack} className="flex items-center gap-2 text-red-500 hover:text-red-400 transition-colors">
                <ArrowLeftIcon />
                Back to Library
            </button>
             <div className="flex items-center gap-4">
                {isCustom && (
                    <>
                        <button onClick={() => onEdit(monster)} title="Edit Monster" className="flex items-center gap-2 text-slate-400 hover:text-white transition-colors">
                            <EditIcon /> <span className="text-sm">Edit</span>
                        </button>
                        <button onClick={() => { if(window.confirm(`Are you sure you want to delete ${monster.name}?`)) onDelete(monster.id) }} title="Delete Monster" className="flex items-center gap-2 text-slate-400 hover:text-red-500 transition-colors">
                            <TrashIcon /> <span className="text-sm">Delete</span>
                        </button>
                    </>
                )}
                <button onClick={handlePrint} disabled={isPrinting} className="flex items-center gap-2 text-red-500 hover:text-red-400 transition-colors disabled:text-slate-500 disabled:cursor-wait">
                    <PrintIcon />
                    {isPrinting ? 'Printing...' : 'Print PDF'}
                </button>
            </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
            <div className="md:col-span-1">
                <img src={monster.imageUrl} alt={monster.name} className="w-full h-auto object-cover rounded-lg shadow-lg" crossOrigin="anonymous" />
            </div>
            <div className="md:col-span-2">
                <h2 className="font-creepster text-5xl text-red-600 mb-2 tracking-wider">{monster.name}</h2>
                <p className="text-lg text-slate-400 mb-6 italic">{monster.archetype}</p>

                <div className="bg-slate-900 p-4 rounded-md mb-6 ring-1 ring-slate-700">
                    <p className="text-slate-300">{monster.history}</p>
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                    <div>
                        <StatBlock title="Atributos">
                            <ul className="list-disc list-inside">
                                {Object.entries(monster.attributes).map(([key, value]) => (
                                    <li key={key}><span className="capitalize font-semibold">{key}:</span> {value}</li>
                                ))}
                            </ul>
                        </StatBlock>
                        <StatBlock title="Perícias">
                            <p>{monster.skills.join(', ')}</p>
                        </StatBlock>
                        <StatBlock title="Combate">
                            <ul className="list-disc list-inside">
                                <li><strong>Aparar:</strong> {monster.parry}</li>
                                <li><strong>Resistência:</strong> {monster.toughness}</li>
                                <li><strong>Movimentação:</strong> {monster.movement}</li>
                                {monster.size != null && <li><strong>Tamanho:</strong> {monster.size}</li>}
                            </ul>
                        </StatBlock>
                    </div>
                    <div>
                        <StatBlock title="Habilidades">
                            <ul className="space-y-2">
                            {monster.abilities.map(ability => (
                                <li key={ability.name}><strong>{ability.name}:</strong> {ability.description}</li>
                            ))}
                            </ul>
                        </StatBlock>
                        {monster.advantages && monster.advantages.length > 0 && <StatBlock title="Vantagens"><p>{monster.advantages.join(', ')}</p></StatBlock>}
                        {monster.complications && monster.complications.length > 0 && <StatBlock title="Complicações"><p>{monster.complications.join(', ')}</p></StatBlock>}
                        {monster.weapons && <StatBlock title="Armas"><p>{monster.weapons}</p></StatBlock>}
                        {monster.powers && <StatBlock title="Poderes"><p>{monster.powers}</p></StatBlock>}
                    </div>
                </div>
            </div>
        </div>
    </div>
  );
};

