const Bestiary: React.FC<{ onEditMonster: (monster: Monster) => void, showCreator: () => void }> = ({ onEditMonster, showCreator }) => {
  const [selectedBook, setSelectedBook] = useState<string | null>(null);
  const [selectedMonster, setSelectedMonster] = useState<Monster | null>(null);
  const [customMonsters, setCustomMonsters] = useState<Monster[]>([]);
  const [showPrintModal, setShowPrintModal] = useState(false);
  const [isPrinting, setIsPrinting] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [sortBy, setSortBy] = useState<'name' | 'archetype'>('name');

  useEffect(() => {
    setCustomMonsters(getCustomMonsters());
  }, []);

  const allMonsters = useMemo(() => [...predefinedMonsters, ...customMonsters], [customMonsters]);

  const books = useMemo(() => {
    const bookMap = allMonsters.reduce((acc, monster) => {
      const book = monster.sourcebook;
      if (!acc[book]) acc[book] = [];
      acc[book].push(monster);
      return acc;
    }, {} as Record<string, Monster[]>);
    return Object.entries(bookMap).sort(([a], [b]) => a.localeCompare(b));
  }, [allMonsters]);

  const handleDelete = (id: string) => {
    deleteCustomMonster(id);
    setCustomMonsters(getCustomMonsters());
    setSelectedMonster(null); 
    setSelectedBook('Custom Creations');
  }

  const handlePrintCollection = async (template: PdfTemplate) => {
    const monstersToPrint = selectedBook ? books.find(([title]) => title === selectedBook)?.[1] || [] : [];
    if (monstersToPrint.length === 0) {
        alert("No monsters in this collection to print.");
        return;
    }
    setIsPrinting(true);
    await generatePdf(monstersToPrint, template);
    setIsPrinting(false);
    setShowPrintModal(false);
  };

  const handleBackToLibrary = () => {
    setSelectedBook(null);
    setSearchTerm('');
    setSortBy('name');
  };

  if (selectedMonster) {
    return <MonsterDetail monster={selectedMonster} onBack={() => setSelectedMonster(null)} onEdit={onEditMonster} onDelete={handleDelete} />;
  }

  if (selectedBook) {
    const monstersInBook = books.find(([title]) => title === selectedBook)?.[1] || [];

    const filteredMonstersInBook = useMemo(() => {
        let result = monstersInBook;

        // Filter
        if (searchTerm.trim()) {
            const lowercasedTerm = searchTerm.toLowerCase();
            result = result.filter(monster => 
                monster.name.toLowerCase().includes(lowercasedTerm) ||
                monster.archetype.toLowerCase().includes(lowercasedTerm)
            );
        }

        // Sort
        return [...result].sort((a, b) => {
             if (sortBy === 'name') {
                 return a.name.localeCompare(b.name);
             } else {
                 return a.archetype.localeCompare(b.archetype);
             }
        });
    }, [monstersInBook, searchTerm, sortBy]);

    return (
        <div>
            <div className="flex flex-wrap justify-between items-center gap-4 mb-6">
                <button onClick={handleBackToLibrary} className="flex items-center gap-2 text-red-500 hover:text-red-400 transition-colors">
                    <ArrowLeftIcon />
                    Back to Library
                </button>
                <div className="flex flex-grow gap-4 items-center flex-wrap sm:flex-nowrap">
                    <div className="relative flex-grow max-w-lg mx-auto sm:mx-0 w-full sm:w-auto">
                        <span className="absolute inset-y-0 left-0 flex items-center pl-3 pointer-events-none">
                            <SearchIcon />
                        </span>
                        <input
                            type="text"
                            placeholder="Search by name or archetype..."
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                            className="w-full bg-slate-800 border-slate-700 rounded-md py-2 pl-10 pr-4 text-slate-200 focus:ring-red-500 focus:border-red-500 transition-colors"
                            aria-label="Search monsters"
                        />
                    </div>

                    <select
                        value={sortBy}
                        onChange={(e) => setSortBy(e.target.value as 'name' | 'archetype')}
                        className="bg-slate-800 border-slate-700 rounded-md py-2 px-3 text-slate-200 focus:ring-red-500 focus:border-red-500 transition-colors cursor-pointer"
                        aria-label="Sort monsters"
                    >
                        <option value="name">Sort by Name</option>
                        <option value="archetype">Sort by Archetype</option>
                    </select>
                </div>

                <button onClick={() => setShowPrintModal(true)} className="flex items-center gap-2 bg-slate-800 px-4 py-2 rounded-md hover:bg-red-700 transition-colors">
                    <PrintIcon /> Print Collection
                </button>
            </div>
            <h2 className="font-creepster text-4xl text-red-600 mb-8 tracking-wider">{selectedBook}</h2>
            {filteredMonstersInBook.length > 0 ? (
                <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-6">
                    {filteredMonstersInBook.map(monster => (
                       <div key={monster.id} onClick={() => setSelectedMonster(monster)} className="bg-slate-800 rounded-lg shadow-lg overflow-hidden cursor-pointer group transition-all duration-300 hover:shadow-red-600/40 hover:scale-105">
                            <img src={monster.imageUrl} alt={monster.name} className="w-full h-48 object-cover" crossOrigin="anonymous" />
                            <div className="p-4">
                                <h3 className="font-creepster text-2xl text-red-500 tracking-wide truncate">{monster.name}</h3>
                                <p className="text-sm text-slate-400 truncate">{monster.archetype}</p>
                            </div>
                        </div>
                    ))}
                </div>
            ) : (
                <div className="text-center py-16">
                    <h3 className="text-2xl font-semibold text-slate-400">No Monsters Found</h3>
                    <p className="text-slate-500 mt-2">Try adjusting your search terms.</p>
                </div>
            )}
            <PrintModal isOpen={showPrintModal} onClose={() => setShowPrintModal(false)} onPrint={handlePrintCollection} isPrinting={isPrinting} />
        </div>
    )
  }

  return (
    <div>
      <h2 className="font-creepster text-4xl text-center text-red-600 mb-8 tracking-wider">The Library</h2>
      <div className="flex flex-wrap justify-center gap-8">
        {books.map(([title, monsters]) => (
            <BookCard key={title} title={title} count={monsters.length} onClick={() => setSelectedBook(title)} />
        ))}
        <AddMonsterCard onClick={showCreator}/>
      </div>
    </div>
  );
};

export default Bestiary;

import { GoogleGenAI } from "@google/genai";

const API_KEY = process.env.API_KEY;

if (!API_KEY) {
  console.warn("API_KEY not found. AI features will be disabled.");
}

const ai = new GoogleGenAI({ apiKey: API_KEY });

export const generateMonsterStory = async (monsterDetails: {
  name: string;
  archetype: string;
  race: string;
  abilities: string;
  skills: string;
  weapons?: string;
  toughness: string;
  attributes: { agility: string, strength: string, vigor: string };
}): Promise<string> => {
  if (!API_KEY) {
    throw new Error("AI features are not configured (API Key missing).");
  }

  const prompt = `
    Create a compelling backstory for a monster designed for the Savage Worlds Adventure Edition (SWADE) roleplaying game.
    The tone should be evocative and fit a "Fast! Furious! Fun!" pulp action/horror setting.
    The output should be a single, well-written paragraph, written as an entry for a bestiary.
    Do not use markdown, titles, or any special formatting. Just the story text.

    Monster Name: ${monsterDetails.name}
    Race: ${monsterDetails.race}
    Archetype: ${monsterDetails.archetype}
    Key Abilities: ${monsterDetails.abilities}
    Notable Skills: ${monsterDetails.skills}
    Toughness: ${monsterDetails.toughness}
    Primary Attributes: Agility ${monsterDetails.attributes.agility}, Strength ${monsterDetails.attributes.strength}, Vigor ${monsterDetails.attributes.vigor}
    Preferred Weapon: ${monsterDetails.weapons || 'Natural weapons'}

    Backstory:
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
    });

    const text = response.text;
    if (!text) {
        throw new Error("Received empty response from AI.");
    }

    return text.trim();
  } catch (error) {
    console.error("Error generating monster story:", error);
    throw new Error("Failed to generate story. Please check your connection and try again.");
  }
};

