                </div>
                <textarea name="history" id="history" value={monster.history} onChange={handleValueChange} rows={6} className="w-full bg-slate-800 border-slate-700 rounded-md p-2 text-slate-200 focus:ring-red-500 focus:border-red-500" placeholder="Describe the monster's origins... or let AI do it for you!"></textarea>
